function median(arr){ var a=arr.slice().sort(function(x,y){return x-y;}); var n=a.length;
  if(!n) return NaN; var m=Math.floor(n/2); return n%2? a[m] : (a[m-1]+a[m])/2; }
function boxStats(arr){
  if(!arr||arr.length<1) return {error:'数据为空'};
  var a=arr.slice().sort(function(x,y){return x-y;}); var n=a.length;
  var med=median(a), q1, q3;
  if(n%2){ var lo=a.slice(0,Math.floor(n/2)), hi=a.slice(Math.floor(n/2)+1); q1=median(lo); q3=median(hi); }
  else { var mid=n/2; q1=median(a.slice(0,mid)); q3=median(a.slice(mid)); }
  var iqr=q3-q1, lf=q1-1.5*iqr, uf=q3+1.5*iqr;
  var outs=[], wl=Infinity, wh=-Infinity;
  for(var i=0;i<n;i++){ if(a[i]<lf||a[i]>uf) outs.push(a[i]); else { if(a[i]<wl) wl=a[i]; if(a[i]>wh) wh=a[i]; } }
  if(wl===Infinity){ wl=a[0]; wh=a[n-1]; }
  return {min:a[0], max:a[n-1], median:med, q1:q1, q3:q3, iqr:iqr, whiskerLow:wl, whiskerHigh:wh, outliers:outs};
}
var EXPORTS={boxStats:boxStats, median:median};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BoxPlotForgePure = EXPORTS; }
